/* CCITT SDL-88 Ping-Pong Request-Response Protocol */
SYSTEM PingPongProtocol;
  SIGNAL Ping, Pong;
  CHANNEL C_Link
    FROM ClientBlock TO ServerBlock WITH Ping;
    FROM ServerBlock TO ClientBlock WITH Pong;
  ENDCHANNEL C_Link;

  BLOCK ClientBlock;
    SIGNALROUTE SR_Client
      FROM Client TO ENV WITH Ping;
      FROM ENV TO Client WITH Pong;
    CONNECT C_Link AND SR_Client;

    PROCESS Client(1, 1);
      TIMER T_Retry;
      START;
        OUTPUT Ping VIA SR_Client;
        SET(NOW + 2.0, T_Retry);
        NEXTSTATE WaitPong;
      STATE WaitPong;
        INPUT Pong;
          RESET(T_Retry);
          OUTPUT Ping VIA SR_Client;
          SET(NOW + 2.0, T_Retry);
          NEXTSTATE WaitPong;
        INPUT T_Retry;
          OUTPUT Ping VIA SR_Client;
          SET(NOW + 2.0, T_Retry);
          NEXTSTATE WaitPong;
      ENDSTATE WaitPong;
    ENDPROCESS Client;
  ENDBLOCK ClientBlock;

  BLOCK ServerBlock;
    SIGNALROUTE SR_Server
      FROM ENV TO Server WITH Ping;
      FROM Server TO ENV WITH Pong;
    CONNECT C_Link AND SR_Server;

    PROCESS Server(1, 1);
      START;
        NEXTSTATE Ready;
      STATE Ready;
        INPUT Ping;
          OUTPUT Pong VIA SR_Server;
          NEXTSTATE Ready;
      ENDSTATE Ready;
    ENDPROCESS Server;
  ENDBLOCK ServerBlock;
ENDSYSTEM PingPongProtocol;

/* SDL-88 Alternating-Bit Reliable Data Link Protocol */
SYSTEM AlternatingBitProtocol;
  SIGNAL DataReq(Integer), Frame(Integer, Integer), Ack(Integer), DataInd(Integer);
  CHANNEL C_Data
    FROM SenderBlock TO ReceiverBlock WITH Frame;
    FROM ReceiverBlock TO SenderBlock WITH Ack;
  ENDCHANNEL C_Data;

  BLOCK SenderBlock;
    SIGNALROUTE SR_S
      FROM Sender TO ENV WITH Frame;
      FROM ENV TO Sender WITH Ack;
    CONNECT C_Data AND SR_S;

    PROCESS Sender(1, 1);
      DCL seq Integer := 0;
      DCL payload Integer := 0;
      TIMER T_Retx;

      START;
        TASK seq := 0;
        NEXTSTATE Idle;

      STATE Idle;
        INPUT DataReq(payload);
          OUTPUT Frame(payload, seq) VIA SR_S;
          SET(NOW + 1.5, T_Retx);
          NEXTSTATE WaitAck;
      ENDSTATE Idle;

      STATE WaitAck;
        INPUT Ack(seq);
          RESET(T_Retx);
          TASK seq := 1 - seq;
          NEXTSTATE Idle;
        INPUT T_Retx;
          OUTPUT Frame(payload, seq) VIA SR_S;
          SET(NOW + 1.5, T_Retx);
          NEXTSTATE -;
      ENDSTATE WaitAck;
    ENDPROCESS Sender;
  ENDBLOCK SenderBlock;

  BLOCK ReceiverBlock;
    SIGNALROUTE SR_R
      FROM ENV TO Receiver WITH Frame;
      FROM Receiver TO ENV WITH Ack;
    CONNECT C_Data AND SR_R;

    PROCESS Receiver(1, 1);
      DCL expected Integer := 0;
      DCL rxPayload Integer := 0;
      DCL rxSeq Integer := 0;

      START;
        NEXTSTATE Ready;

      STATE Ready;
        INPUT Frame(rxPayload, rxSeq);
          DECISION rxSeq = expected;
            (TRUE):
              OUTPUT DataInd(rxPayload) TO ENV;
              OUTPUT Ack(rxSeq) VIA SR_R;
              TASK expected := 1 - expected;
              NEXTSTATE Ready;
            ELSE:
              OUTPUT Ack(rxSeq) VIA SR_R;
              NEXTSTATE -;
          ENDDECISION;
      ENDSTATE Ready;
    ENDPROCESS Receiver;
  ENDBLOCK ReceiverBlock;
ENDSYSTEM AlternatingBitProtocol;

/* SDL-88 Automated Vending Machine Coin & Dispense Controller */
SYSTEM VendingMachine;
  SIGNAL Coin(Integer), SelectItem(Integer), Cancel, Dispense(Integer), Refund(Integer), VendDone;

  BLOCK ControllerBlock;
    PROCESS Dispenser(1, 1);
      DCL credit Integer := 0;
      DCL coinVal Integer := 0;
      DCL itemCode Integer := 0;
      DCL price Integer := 100;
      TIMER T_Vend;

      START;
        TASK credit := 0;
        NEXTSTATE Idle;

      STATE Idle;
        INPUT Coin(coinVal);
          TASK credit := credit + coinVal;
          NEXTSTATE Accepting;
      ENDSTATE Idle;

      STATE Accepting;
        INPUT Coin(coinVal);
          TASK credit := credit + coinVal;
          NEXTSTATE Accepting;
        INPUT SelectItem(itemCode);
          DECISION credit >= price;
            (TRUE):
              TASK credit := credit - price;
              OUTPUT Dispense(itemCode) TO ENV;
              SET(NOW + 5.0, T_Vend);
              NEXTSTATE Dispensing;
            ELSE:
              NEXTSTATE Accepting;
          ENDDECISION;
        INPUT Cancel;
          OUTPUT Refund(credit) TO ENV;
          TASK credit := 0;
          NEXTSTATE Idle;
      ENDSTATE Accepting;

      STATE Dispensing;
        INPUT VendDone;
          RESET(T_Vend);
          DECISION credit > 0;
            (TRUE):
              OUTPUT Refund(credit) TO ENV;
              TASK credit := 0;
              NEXTSTATE Idle;
            ELSE:
              NEXTSTATE Idle;
          ENDDECISION;
        INPUT T_Vend;
          OUTPUT Refund(credit) TO ENV;
          TASK credit := 0;
          NEXTSTATE Idle;
      ENDSTATE Dispensing;
    ENDPROCESS Dispenser;
  ENDBLOCK ControllerBlock;
ENDSYSTEM VendingMachine;

/* SDL-88 Telecom Call Setup, Alerting, Active Speech & Teardown Signaling */
SYSTEM TelecomCallControl;
  SIGNAL DialReq(Integer), Setup(Integer), Alert, Connect, ConnectAck, Hangup, Release, ReleaseComp;

  CHANNEL C_Trunk
    FROM OrigExchange TO TermExchange WITH Setup, ConnectAck, Release;
    FROM TermExchange TO OrigExchange WITH Alert, Connect, ReleaseComp;
  ENDCHANNEL C_Trunk;

  BLOCK OrigExchange;
    SIGNALROUTE SR_Orig
      FROM CallerFSM TO ENV WITH Setup, ConnectAck, Release;
      FROM ENV TO CallerFSM WITH Alert, Connect, ReleaseComp;
    CONNECT C_Trunk AND SR_Orig;

    PROCESS CallerFSM(1, 1);
      DCL destNum Integer := 0;
      TIMER T_NoAnswer;

      START;
        NEXTSTATE NullState;

      STATE NullState;
        INPUT DialReq(destNum);
          OUTPUT Setup(destNum) VIA SR_Orig;
          SET(NOW + 30.0, T_NoAnswer);
          NEXTSTATE CallProceeding;
      ENDSTATE NullState;

      STATE CallProceeding;
        INPUT Alert;
          NEXTSTATE Ringing;
        INPUT T_NoAnswer;
          OUTPUT Release VIA SR_Orig;
          NEXTSTATE Releasing;
      ENDSTATE CallProceeding;

      STATE Ringing;
        INPUT Connect;
          RESET(T_NoAnswer);
          OUTPUT ConnectAck VIA SR_Orig;
          NEXTSTATE ActiveCall;
        INPUT Hangup;
          RESET(T_NoAnswer);
          OUTPUT Release VIA SR_Orig;
          NEXTSTATE Releasing;
        INPUT T_NoAnswer;
          OUTPUT Release VIA SR_Orig;
          NEXTSTATE Releasing;
      ENDSTATE Ringing;

      STATE ActiveCall;
        INPUT Hangup;
          OUTPUT Release VIA SR_Orig;
          NEXTSTATE Releasing;
      ENDSTATE ActiveCall;

      STATE Releasing;
        INPUT ReleaseComp;
          NEXTSTATE NullState;
      ENDSTATE Releasing;
    ENDPROCESS CallerFSM;
  ENDBLOCK OrigExchange;

  BLOCK TermExchange;
    SIGNALROUTE SR_Term
      FROM ENV TO CalleeFSM WITH Setup, ConnectAck, Release;
      FROM CalleeFSM TO ENV WITH Alert, Connect, ReleaseComp;
    CONNECT C_Trunk AND SR_Term;

    PROCESS CalleeFSM(1, 1);
      DCL calledId Integer := 0;
      TIMER T_Ring;

      START;
        NEXTSTATE Idle;

      STATE Idle;
        INPUT Setup(calledId);
          OUTPUT Alert VIA SR_Term;
          SET(NOW + 3.0, T_Ring);
          NEXTSTATE Alerting;
      ENDSTATE Idle;

      STATE Alerting;
        INPUT T_Ring;
          OUTPUT Connect VIA SR_Term;
          NEXTSTATE WaitAck;
        INPUT Release;
          RESET(T_Ring);
          OUTPUT ReleaseComp VIA SR_Term;
          NEXTSTATE Idle;
      ENDSTATE Alerting;

      STATE WaitAck;
        INPUT ConnectAck;
          NEXTSTATE Connected;
        INPUT Release;
          OUTPUT ReleaseComp VIA SR_Term;
          NEXTSTATE Idle;
      ENDSTATE WaitAck;

      STATE Connected;
        INPUT Release;
          OUTPUT ReleaseComp VIA SR_Term;
          NEXTSTATE Idle;
      ENDSTATE Connected;
    ENDPROCESS CalleeFSM;
  ENDBLOCK TermExchange;
ENDSYSTEM TelecomCallControl;

/* SDL-88 Multi-Block Industrial Safety PLC Emergency Shutdown Interlock */
SYSTEM SafetyPlcInterlock;
  SIGNAL SensorSample(Integer), HighAlarm, ResetReq, TripCmd, OpenCmd, ValveClosed, ValveOpen;

  CHANNEL C_SensToPlc
    FROM SensorBlock TO LogicSolverBlock WITH HighAlarm;
  ENDCHANNEL C_SensToPlc;

  CHANNEL C_PlcToValve
    FROM LogicSolverBlock TO ActuatorBlock WITH TripCmd, OpenCmd;
    FROM ActuatorBlock TO LogicSolverBlock WITH ValveClosed, ValveOpen;
  ENDCHANNEL C_PlcToValve;

  BLOCK SensorBlock;
    SIGNALROUTE SR_Sens
      FROM PressureMonitor TO ENV WITH HighAlarm;
    CONNECT C_SensToPlc AND SR_Sens;

    PROCESS PressureMonitor(1, 1);
      DCL pressure Integer := 0;
      DCL tripLimit Integer := 120;

      START;
        NEXTSTATE Monitoring;

      STATE Monitoring;
        INPUT SensorSample(pressure);
          DECISION pressure >= tripLimit;
            (TRUE):
              OUTPUT HighAlarm VIA SR_Sens;
              NEXTSTATE Monitoring;
            ELSE:
              NEXTSTATE Monitoring;
          ENDDECISION;
      ENDSTATE Monitoring;
    ENDPROCESS PressureMonitor;
  ENDBLOCK SensorBlock;

  BLOCK LogicSolverBlock;
    SIGNALROUTE SR_FromSens
      FROM ENV TO SafetySolver WITH HighAlarm;
    CONNECT C_SensToPlc AND SR_FromSens;

    SIGNALROUTE SR_ToValve
      FROM SafetySolver TO ENV WITH TripCmd, OpenCmd;
      FROM ENV TO SafetySolver WITH ValveClosed, ValveOpen;
    CONNECT C_PlcToValve AND SR_ToValve;

    PROCESS SafetySolver(1, 1);
      TIMER T_Stroke;

      START;
        NEXTSTATE NormalRun;

      STATE NormalRun;
        INPUT HighAlarm;
          OUTPUT TripCmd VIA SR_ToValve;
          SET(NOW + 2.0, T_Stroke);
          NEXTSTATE Tripping;
      ENDSTATE NormalRun;

      STATE Tripping;
        INPUT ValveClosed;
          RESET(T_Stroke);
          NEXTSTATE SafeShutdown;
        INPUT T_Stroke;
          OUTPUT TripCmd VIA SR_ToValve;
          NEXTSTATE SafeShutdown;
      ENDSTATE Tripping;

      STATE SafeShutdown;
        INPUT ResetReq;
          OUTPUT OpenCmd VIA SR_ToValve;
          NEXTSTATE Restarting;
      ENDSTATE SafeShutdown;

      STATE Restarting;
        INPUT ValveOpen;
          NEXTSTATE NormalRun;
        INPUT HighAlarm;
          OUTPUT TripCmd VIA SR_ToValve;
          SET(NOW + 2.0, T_Stroke);
          NEXTSTATE Tripping;
      ENDSTATE Restarting;
    ENDPROCESS SafetySolver;
  ENDBLOCK LogicSolverBlock;

  BLOCK ActuatorBlock;
    SIGNALROUTE SR_Valve
      FROM ENV TO EsdValve WITH TripCmd, OpenCmd;
      FROM EsdValve TO ENV WITH ValveClosed, ValveOpen;
    CONNECT C_PlcToValve AND SR_Valve;

    PROCESS EsdValve(1, 1);
      START;
        NEXTSTATE OpenPos;

      STATE OpenPos;
        INPUT TripCmd;
          OUTPUT ValveClosed VIA SR_Valve;
          NEXTSTATE ClosedPos;
      ENDSTATE OpenPos;

      STATE ClosedPos;
        INPUT OpenCmd;
          OUTPUT ValveOpen VIA SR_Valve;
          NEXTSTATE OpenPos;
      ENDSTATE ClosedPos;
    ENDPROCESS EsdValve;
  ENDBLOCK ActuatorBlock;
ENDSYSTEM SafetyPlcInterlock;
